test('invoiceTotals with fractional VAT calculation', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set', qty: 1, unitPrice: 980, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line: 980, discount = 49, after = 931, VAT = 931 * 0.21 = 195.51 → 196
  assert.equal(totals.subtotal, 980);
  assert.equal(totals.discount, 49);
  assert.equal(totals.vat, 196);
});

