      { sku: 'STICKER', name: 'Sticker', qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line: 9 * 1000 = 9000
  // No discounts
  // VAT: 9000 * 0.21 = 1890
