test('invoiceTotals with mixed discounts and VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'BOOK-DESIGN', name: 'Design handbook', qty: 2, unitPrice: 2490, vatRate: 9, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 10 * 8500 = 85000, discount = 8500, after = 76500, VAT = 76500 * 0.21 = 16065
  // Line 2: 2 * 2490 = 4980, discount = 0, after = 4980, VAT = 4980 * 0.09 = 448.2 ≈ 448
  // Subtotal: 89980
  // Total discount: 8500
  // Total VAT: 16513
  // Total: 89980 - 8500 + 16513 = 97993
  assert.equal(totals.subtotal, 89980);
