    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
    voucher: { code: 'SUMMER2026', amount: 5000 },
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 42500
  // Discount: 4250
  // After discount: 38250
  // VAT: 38250 * 0.21 = 8032.5 → 8032
  // Voucher: 5000
  // Total: 38250 + 8032 - 5000 = 41282
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 8032);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 41282);
});

test('applyVoucher preserves voucher through addLine', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'SUMMER2026', amount: 10000 });
  const addLineResult = addLine(voucherResult.value, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(addLineResult.ok, true);
  assert.equal(addLineResult.value.voucher.code, 'SUMMER2026');
  assert.equal(addLineResult.value.voucher.amount, 10000);
});

