    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'STICKER', name: 'Sticker', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line: 10 * 1000 = 10000
  // First discount: 0%
  // Bulk discount: 10000 * 0.025 = 250
  // After discounts: 9750
  // VAT: 9750 * 0.21 = 2047.5 → 2048 (rounded, 0.5 rounds to even)
  // Total: 10000 - 250 + 2048 = 11798
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 2048);
  assert.equal(totals.total, 11798);
});

