    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 42500, discount = 4250, after discount = 38250, VAT = 8032.5 → 8032
  // Line 2: 120000, discount = 6000, after discount = 114000, VAT = 23940
  // Subtotal: 162500
  // Total discount: 10250
  // Total VAT: 31972
  // Total: 162500 - 10250 + 31972 = 184222
  assert.equal(totals.subtotal, 162500);
  assert.equal(totals.discount, 10250);
  assert.equal(totals.vat, 31972);
  assert.equal(totals.total, 184222);
});

