import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal with single quantity', () => {
  const line = { qty: 1, unitPrice: 8500 };
  assert.equal(lineTotal(line), 8500);
});

test('lineTotal with zero quantity', () => {
  const line = { qty: 0, unitPrice: 8500 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal with large values', () => {
  const line = { qty: 1000, unitPrice: 100000 };
  assert.equal(lineTotal(line), 100000000);
});

test('lineTotal with fractional price (should not happen)', () => {
  const line = { qty: 5, unitPrice: 8500.5 };
  assert.equal(lineTotal(line), 42502.5);
});

test('invoiceTotals sums line totals correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 42500 + 120000 = 162500
  // VAT: (42500 * 0.21) + (120000 * 0.21) = 8925 + 25200 = 34125
  // Total: 162500 + 34125 = 196625
  assert.equal(totals.subtotal, 162500);
  assert.equal(totals.vat, 34125);
  assert.equal(totals.total, 196625);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 25500
  // VAT: 25500 * 0.21 = 5355
  // Total: 25500 + 5355 = 30855
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.vat, 5355);
  assert.equal(totals.total, 30855);
});

test('invoiceTotals calculates discount on a single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line total: 5 * 8500 = 42500
  // Discount: 42500 * 10 / 100 = 4250
  // Amount after discount: 42500 - 4250 = 38250
  // VAT: 38250 * 21 / 100 = 8032.5 → 8032 (banker's rounding)
  // Total: 38250 + 8032 = 46282
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 4250);
  assert.equal(totals.vat, 8032);
  assert.equal(totals.total, 46282);
});

test('invoiceTotals calculates discount on multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 42500, discount = 4250, after discount = 38250, VAT = 8032.5 → 8032
  // Line 2: 120000, discount = 6000, after discount = 114000, VAT = 23940
  // Subtotal: 162500
  // Total discount: 10250
  // Total VAT: 31972
  // Total: 162500 - 10250 + 31972 = 184222
  assert.equal(totals.subtotal, 162500);
  assert.equal(totals.discount, 10250);
  assert.equal(totals.vat, 31972);
  assert.equal(totals.total, 184222);
});

