test('invoiceTotals with different VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'PRINT-A4', name: 'Printed flyer A4', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 100 * 37 = 3700, bulk disc = 92.5, after = 3607.5, VAT = 325
  // Line 2: 1 * 60000 = 60000, VAT = 0
  // Subtotal: 63700
  // Discount: 92.5
  // Total VAT: 325
  // Total: 63700 - 92.5 + 325 = 63932.5
