test('invoiceTotals bulk discount with mixed line and bulk on some lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'PRODUCT-A', name: 'Product A', qty: 15, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
      { sku: 'PRODUCT-B', name: 'Product B', qty: 5, unitPrice: 2000, vatRate: 21, discountPercent: 5 },
      { sku: 'PRODUCT-C', name: 'Product C', qty: 20, unitPrice: 500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Line A: 15 * 1000 = 15000, first disc = 1500, bulk = 337.5 → 338, total disc = 1838, after = 13162, vat = 2764
  // Line B: 5 * 2000 = 10000, disc = 500, no bulk, after = 9500, vat = 1995
  // Line C: 20 * 500 = 10000, bulk = 250, after = 9750, vat = 2048
  // Subtotal: 35000
  // Total discount: 1838 + 500 + 250 = 2588
  // Total VAT: 6807
  // Total: 35000 - 2588 + 6807 = 39219
  assert.equal(totals.subtotal, 35000);
  assert.ok(totals.discount > 2000);
  assert.ok(totals.vat > 6000);
});
